// Normalize Incoming Email — v7
// All emails processed — no subject filter.
// Checks staticData: if conversationId already mapped → isFollowUp=true (thread reply).
// Always returns 1 item with shouldPost + skipReason + isFollowUp.

const item = $input.first().json;

function getEmailAddress(obj) {
  const ea = obj?.emailAddress || obj || {};
  return {
    name: String(ea.name || ea.displayName || '').trim(),
    address: String(ea.address || ea.email || ea.emailAddress || '').toLowerCase().trim(),
  };
}

function htmlToText(input) {
  if (!input) return '';
  return String(input)
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function stripQuotedHistory(text) {
  if (!text) return '';
  const markers = [
    /\n-{2,}\s*Original Message\s*-{2,}/i,
    /\nОт:\s.+/i,
    /\nFrom:\s.+/i,
    /\nOn .+ wrote:/i,
    /\n.*написал\(а\):/i,
    /\n________________________________\s*\n/i
  ];
  let cutIndex = -1;
  for (const marker of markers) {
    const match = marker.exec(text);
    if (match && (cutIndex === -1 || match.index < cutIndex)) {
      cutIndex = match.index;
    }
  }
  return cutIndex >= 0 ? text.slice(0, cutIndex).trim() : text.trim();
}

function stop(reason, extra = {}) {
  return [{
    json: {
      shouldPost: false,
      skipReason: reason,
      isFollowUp: false,
      requestId: '—',
      senderEmail: '',
      senderName: '',
      subject: String(item.subject || ''),
      cleanBody: '',
      messageId: item.id || item.messageId || null,
      conversationId: item.conversationId || null,
      ...extra
    }
  }];
}

const messageId = item.id || item.messageId || null;
const internetMessageId = item.internetMessageId || null;
const conversationId = item.conversationId || null;
const subject = String(item.subject || '').trim();

if (!messageId) return stop('messageId missing');
if (!conversationId) return stop('conversationId missing');
if (item.isDraft === true) return stop('item is draft');

const rawBody = item.body?.content || item.bodyPreview || '';
let cleanBody = htmlToText(rawBody);

// For follow-up messages strip quoted history so only new text is shown
cleanBody = stripQuotedHistory(cleanBody);

const requestIdMatch =
  cleanBody.match(/ID\s*обращения\s*[:：]\s*(\d+)/i) ||
  cleanBody.match(/\bID\s*[:：]\s*(\d+)/i);
const requestId = requestIdMatch?.[1] || '—';

const embeddedSenderMatch = cleanBody.match(/Отправлено от\s+([^\s<>]+@[^\s<>]+)/i);
const embeddedSenderEmail = embeddedSenderMatch?.[1]?.toLowerCase()?.trim() || '';

const explicitEmailMatch = cleanBody.match(/Email\s*[:：]\s*([^\s<>]+@[^\s<>]+)/i);
const explicitEmail = explicitEmailMatch?.[1]?.toLowerCase()?.trim() || '';

cleanBody = cleanBody
  .replace(/\n?\s*Отправлено от\s+[^\s<>]+@[^\s<>]+/i, '')
  .replace(/^\s*ID\s*обращения\s*[:：]\s*\d+\s*$/gim, '')
  .replace(/^\s*ID\s*[:：]\s*\d+\s*$/gim, '')
  .replace(/^\s*Email\s*[:：]\s*[^\s<>]+@[^\s<>]+\s*$/gim, '')
  .replace(/^\s*Сообщение\s*[:：]\s*/gim, '')
  .replace(/Outlook:\s*https?:\/\/\S+/gi, '')
  .trim();

const from = getEmailAddress(item.from);
const sender = getEmailAddress(item.sender);

const replyTo = Array.isArray(item.replyTo) && item.replyTo.length
  ? getEmailAddress(item.replyTo[0])
  : { name: '', address: '' };

const ccCustomer = Array.isArray(item.ccRecipients)
  ? item.ccRecipients
      .map(getEmailAddress)
      .find(e =>
        e.address &&
        !e.address.includes('support@tooba.com') &&
        !e.address.includes('@tooba.com') &&
        !e.address.includes('@mx.tooba.com')
      )
  : null;

let customer =
  replyTo.address
    ? replyTo
    : ccCustomer?.address
      ? ccCustomer
      : explicitEmail
        ? { name: explicitEmail, address: explicitEmail }
        : embeddedSenderEmail
          ? { name: embeddedSenderEmail, address: embeddedSenderEmail }
          : from.address
            ? from
            : sender;

let senderEmail = customer.address || '';
let senderName = customer.name || senderEmail;

if (!senderEmail) {
  return stop('senderEmail not found', { from, sender, replyTo, ccCustomer, explicitEmail, embeddedSenderEmail });
}
if (senderEmail === 'unknown') return stop('senderEmail is unknown', { senderEmail });
if (senderEmail.includes('support@tooba.com')) return stop('own support email ignored', { senderEmail });
if (senderEmail.includes('no-reply@mx.tooba.com')) {
  return stop('technical no-reply ignored because real customer not found', { senderEmail, replyTo, ccCustomer });
}

if (!senderName || senderName.toLowerCase() === senderEmail.toLowerCase()) {
  senderName = senderEmail;
}

if (!cleanBody || cleanBody.length < 3) return stop('cleanBody too short', { senderEmail });

// Check if this conversationId is already in staticData (follow-up from same customer)
const sd = $getWorkflowStaticData('global');
const existingMapping = sd.conversationToSlackThread && sd.conversationToSlackThread[conversationId];

const isFollowUp = !!existingMapping;
const slackChannelId = existingMapping ? existingMapping.channelId : null;
const slackThreadTs = existingMapping ? existingMapping.threadTs : null;

return [{
  json: {
    shouldPost: true,
    skipReason: '',
    isFollowUp,
    requestId,
    senderEmail,
    senderName,
    subject,
    cleanBody,
    messageId,
    internetMessageId,
    conversationId,
    slackChannelId,
    slackThreadTs,
    webLink: item.webLink || null,
    receivedDateTime: item.receivedDateTime || null
  }
}];

