const email = $('📧 Normalize Incoming Email').first().json;
const slack = $('💬 Post Request to Slack').first().json;

const channelId = 'C0ATU9ZD2UF';
const threadTs = slack.ts;

if (!email.conversationId || !threadTs) {
  return [];
}

const sd = $getWorkflowStaticData('global');

if (!sd.conversationToSlackThread) {
  sd.conversationToSlackThread = {};
}

sd.conversationToSlackThread[email.conversationId] = {
  channelId,
  threadTs,
  requestId: email.requestId || '—',
  senderEmail: email.senderEmail,
  subject: email.subject,
  originalMessageId: email.messageId,
  storedAt: new Date().toISOString()
};

return [{
  json: {
    ok: true,
    conversationId: email.conversationId,
    channelId,
    threadTs
  }
}];

// Normalize Sent Reply — v8
// Always returns 1 item with hasMapping flag (unless message should be ignored).
// hasMapping=true → direct path to thread reply.
// hasMapping=false → recovery path: fetch original + create card + then thread reply.

const item = $input.first().json;

function getEmailAddress(obj) {
  const ea = obj?.emailAddress || obj || {};
  return {
    name: String(ea.name || ea.displayName || '').trim(),
    address: String(ea.address || ea.email || ea.emailAddress || '').toLowerCase().trim(),
  };
}

function htmlToText(input) {
  if (!input) return '';
  return String(input)
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function stripQuotedHistory(text) {
  if (!text) return '';
  const markers = [
    /\n-{2,}\s*Original Message\s*-{2,}/i,
    /\nОт:\s.+/i,
    /\nFrom:\s.+/i,
    /\nOn .+ wrote:/i,
    /\n.*написал\(а\):/i,
    /\n________________________________\s*\n/i
  ];
  let cutIndex = -1;
  for (const marker of markers) {
    const match = marker.exec(text);
    if (match && (cutIndex === -1 || match.index < cutIndex)) {
      cutIndex = match.index;
    }
  }
  return cutIndex >= 0 ? text.slice(0, cutIndex).trim() : text.trim();
}

const messageId = item.id || item.messageId || null;
const conversationId = item.conversationId || null;
const subject = String(item.subject || '').trim();

if (!messageId) return [];
if (!conversationId) return [];
if (item.isDraft === true) return [];

const sd = $getWorkflowStaticData('global');

if (!sd.processedSentMessageIds) sd.processedSentMessageIds = [];
if (sd.processedSentMessageIds.includes(messageId)) return [];

const from = getEmailAddress(item.from || item.sender);
const toRecipients = Array.isArray(item.toRecipients)
  ? item.toRecipients.map(getEmailAddress).filter(e => e.address)
  : [];

const rawBody = item.body?.content || item.bodyPreview || '';
let sentReplyText = stripQuotedHistory(htmlToText(rawBody));
sentReplyText = sentReplyText.replace(/^\s*Получите Outlook для .+$/gim, '').trim();

if (!sentReplyText || sentReplyText.length < 2) return [];

// Mark processed (ring-buffer)
sd.processedSentMessageIds.push(messageId);
if (sd.processedSentMessageIds.length > 500) {
  sd.processedSentMessageIds = sd.processedSentMessageIds.slice(-500);
}

const mapping = sd.conversationToSlackThread && sd.conversationToSlackThread[conversationId];

if (mapping) {
  // Direct path — Branch A already created the Slack card
  return [{
    json: {
      hasMapping: true,
      messageId,
      conversationId,
      subject,
      fromEmail: from.address,
      fromName: from.name || from.address,
      toEmails: toRecipients.map(e => e.address).join(', '),
      sentReplyText,
      slackChannelId: mapping.channelId,
      slackThreadTs: mapping.threadTs,
      requestId: mapping.requestId || '—',
      originalSenderEmail: mapping.senderEmail || '',
      sentDateTime: item.sentDateTime || null
    }
  }];
}

// Recovery path — Branch A has not run yet, fetch original email from Inbox
return [{
  json: {
    hasMapping: false,
    messageId,
    conversationId,
    subject,
    fromEmail: from.address,
    fromName: from.name || from.address,
    toEmails: toRecipients.map(e => e.address).join(', '),
    sentReplyText,
    sentDateTime: item.sentDateTime || null
  }
}];

// Recover & Build Card — v8
// Takes Microsoft Graph response (messages in the conversation)
// + sent reply data from upstream Normalize Sent Reply.
// Selects the customer's original email and normalizes it like Branch A.

const httpResponse = $input.first().json;
const sentData = $('📧 Normalize Sent Reply').first().json;

// Graph returns { value: [ ...messages ] }
const messages = Array.isArray(httpResponse?.value)
  ? httpResponse.value
  : Array.isArray(httpResponse)
    ? httpResponse
    : [];

function getEmailAddress(obj) {
  const ea = obj?.emailAddress || obj || {};
  return {
    name: String(ea.name || ea.displayName || '').trim(),
    address: String(ea.address || ea.email || ea.emailAddress || '').toLowerCase().trim(),
  };
}

function htmlToText(input) {
  if (!input) return '';
  return String(input)
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function stripQuotedHistory(text) {
  if (!text) return '';
  const markers = [
    /\n-{2,}\s*Original Message\s*-{2,}/i,
    /\nОт:\s.+/i,
    /\nFrom:\s.+/i,
    /\nOn .+ wrote:/i,
    /\n.*написал\(а\):/i,
    /\n________________________________\s*\n/i
  ];
  let cutIndex = -1;
  for (const marker of markers) {
    const match = marker.exec(text);
    if (match && (cutIndex === -1 || match.index < cutIndex)) {
      cutIndex = match.index;
    }
  }
  return cutIndex >= 0 ? text.slice(0, cutIndex).trim() : text.trim();
}

// Pick the customer's original message (oldest, not from support@tooba.com)
const candidates = messages
  .filter(m => {
    const fromAddr = (m.from?.emailAddress?.address || m.sender?.emailAddress?.address || '').toLowerCase();
    return !fromAddr.includes('support@tooba.com');
  })
  .sort((a, b) => {
    const da = new Date(a.receivedDateTime || a.sentDateTime || 0).getTime();
    const db = new Date(b.receivedDateTime || b.sentDateTime || 0).getTime();
    return da - db;
  });

const customerMsg = candidates[0] || messages[0];

if (!customerMsg) {
  // Fallback — synthesize from sent reply data only
  return [{
    json: {
      recoveredMessageId: null,
      conversationId: sentData.conversationId,
      subject: sentData.subject || '(без темы)',
      cleanBody: '(оригинальное письмо клиента не найдено в Inbox)',
      senderEmail: sentData.toEmails || 'unknown',
      senderName: sentData.toEmails || 'unknown',
      requestId: '—',
      sentReplyText: sentData.sentReplyText,
      toEmails: sentData.toEmails,
      fromEmail: sentData.fromEmail
    }
  }];
}

const subject = String(customerMsg.subject || sentData.subject || '').trim();
const rawBody = customerMsg.body?.content || customerMsg.bodyPreview || '';
let cleanBody = stripQuotedHistory(htmlToText(rawBody));

const requestIdMatch =
  cleanBody.match(/ID\s*обращения\s*[:：]\s*(\d+)/i) ||
  cleanBody.match(/\bID\s*[:：]\s*(\d+)/i);
const requestId = requestIdMatch?.[1] || '—';

const explicitEmailMatch = cleanBody.match(/Email\s*[:：]\s*([^\s<>]+@[^\s<>]+)/i);
const explicitEmail = explicitEmailMatch?.[1]?.toLowerCase()?.trim() || '';

const embeddedSenderMatch = cleanBody.match(/Отправлено от\s+([^\s<>]+@[^\s<>]+)/i);
const embeddedSenderEmail = embeddedSenderMatch?.[1]?.toLowerCase()?.trim() || '';

cleanBody = cleanBody
  .replace(/\n?\s*Отправлено от\s+[^\s<>]+@[^\s<>]+/i, '')
  .replace(/^\s*ID\s*обращения\s*[:：]\s*\d+\s*$/gim, '')
  .replace(/^\s*ID\s*[:：]\s*\d+\s*$/gim, '')
  .replace(/^\s*Email\s*[:：]\s*[^\s<>]+@[^\s<>]+\s*$/gim, '')
  .replace(/^\s*Сообщение\s*[:：]\s*/gim, '')
  .replace(/Outlook:\s*https?:\/\/\S+/gi, '')
  .trim();

const from = getEmailAddress(customerMsg.from);
const sender = getEmailAddress(customerMsg.sender);
const replyTo = Array.isArray(customerMsg.replyTo) && customerMsg.replyTo.length
  ? getEmailAddress(customerMsg.replyTo[0])
  : { name: '', address: '' };

const ccCustomer = Array.isArray(customerMsg.ccRecipients)
  ? customerMsg.ccRecipients
      .map(getEmailAddress)
      .find(e =>
        e.address &&
        !e.address.includes('support@tooba.com') &&
        !e.address.includes('@tooba.com') &&
        !e.address.includes('@mx.tooba.com')
      )
  : null;

const customer =
  replyTo.address ? replyTo
  : ccCustomer?.address ? ccCustomer
  : explicitEmail ? { name: explicitEmail, address: explicitEmail }
  : embeddedSenderEmail ? { name: embeddedSenderEmail, address: embeddedSenderEmail }
  : from.address ? from
  : sender;

let senderEmail = customer.address || sentData.toEmails || '';
let senderName = customer.name || senderEmail;

if (!senderName || senderName.toLowerCase() === senderEmail.toLowerCase()) {
  senderName = senderEmail;
}

if (!cleanBody || cleanBody.length < 3) {
  cleanBody = '(тело письма не извлечено)';
}

return [{
  json: {
    recoveredMessageId: customerMsg.id || null,
    conversationId: sentData.conversationId,
    subject,
    cleanBody,
    senderEmail,
    senderName,
    requestId,
    // Carry forward sent reply data for the final thread post
    sentReplyText: sentData.sentReplyText,
    toEmails: sentData.toEmails,
    fromEmail: sentData.fromEmail
  }
}];

// Store Recovery Mapping + Merge — v8
// Stores conversationId → threadTs mapping (so future replies use direct path),
// then forwards merged data to Post Final Reply to Slack Thread.

const data = $('📧 Recover & Build Card').first().json;
const slack = $('💬 Post Recovery Card to Slack').first().json;

const channelId = 'C0ATU9ZD2UF';
const threadTs = slack.ts;

if (!data.conversationId || !threadTs) {
  return [];
}

const sd = $getWorkflowStaticData('global');
if (!sd.conversationToSlackThread) sd.conversationToSlackThread = {};

sd.conversationToSlackThread[data.conversationId] = {
  channelId,
  threadTs,
  requestId: data.requestId || '—',
  senderEmail: data.senderEmail,
  subject: data.subject,
  originalMessageId: data.recoveredMessageId,
  storedAt: new Date().toISOString(),
  recovered: true
};

return [{
  json: {
    slackChannelId: channelId,
    slackThreadTs: threadTs,
    toEmails: data.toEmails,
    originalSenderEmail: data.senderEmail,
    sentReplyText: data.sentReplyText,
    requestId: data.requestId || '—',
    conversationId: data.conversationId
  }
}];

